package com.example.conexionrealtimedatabase;
import android.app.*;import android.content.*;import android.os.Bundle;import android.view.View;import android.widget.*;
public class PatientProfileActivity extends Activity{
 private PatientStore store;private String id;
 @Override public void onCreate(Bundle b){super.onCreate(b);store=new PatientStore(this);id=getIntent().getStringExtra("nuhsa");getWindow().setStatusBarColor(Ui.BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);render();}
 @Override protected void onResume(){super.onResume();if(store!=null)render();}
 private void render(){Patient p=store.get(id);if(p==null){finish();return;}LinearLayout page=Ui.page(this);page.addView(Ui.text(this,"FICHA DE PACIENTE",13,Ui.TEAL,true));page.addView(Ui.heading(this,p.getNombre()+" "+p.getApellidos()));LinearLayout card=Ui.card(this);card.addView(Ui.text(this,"Identificador",14,Ui.MUTED,false));card.addView(Ui.text(this,p.getNuhsa(),19,Ui.INK,true));card.addView(Ui.text(this,"Grupo sanguíneo",14,Ui.MUTED,false));card.addView(Ui.text(this,p.getGrupoSanguineo(),19,Ui.INK,true));page.addView(card);
 Button appointments=Ui.button(this,"Ver y programar citas",true);appointments.setOnClickListener(v->{Intent i=new Intent(this,AppointmentActivity.class);i.putExtra("nuhsa",id);startActivity(i);});page.addView(appointments);Button edit=Ui.button(this,"Editar ficha",false);edit.setOnClickListener(v->{Intent i=new Intent(this,PatientFormActivity.class);i.putExtra("nuhsa",id);startActivity(i);});page.addView(edit);Button del=Ui.button(this,"Eliminar ficha",false);del.setContentDescription("Eliminar ficha del paciente");del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Eliminar ficha").setMessage("Se eliminarán también las citas de este paciente. ¿Continuar?").setNegativeButton("Cancelar",null).setPositiveButton("Eliminar",(d,w)->{store.delete(id);finish();}).show());page.addView(del);Ui.showWithBack(this,page,"pacientes");}
}
